import { createDocumentHandler } from "@/lib/artifacts/server";
import { decodePdfRef, encodePdfRef } from "@/lib/pdf/ref";

/**
 * PDFs are never generated by the model.
 *
 * Every PDF version comes from a deterministic operation (upload, merge, split,
 * rotate, arrange), so the streaming callbacks have nothing to stream. What they
 * must do instead is hand the client the *reference* — never the bytes, which
 * cannot ride a UI message stream.
 */
export const pdfDocumentHandler = createDocumentHandler<"pdf">({
  kind: "pdf",
  onCreateDocument: ({ dataStream, title }) => {
    dataStream.write({
      data: "",
      transient: true,
      type: "data-pdfDelta",
    });

    return Promise.resolve(encodePdfRef({ filename: title, storageKey: "" }));
  },
  onUpdateDocument: ({ document, dataStream }) => {
    // Re-emit the existing reference so the studio can remount without a refetch.
    const ref = decodePdfRef(document.content);

    dataStream.write({
      data: ref?.storageKey ?? "",
      transient: true,
      type: "data-pdfDelta",
    });

    return Promise.resolve(document.content ?? "");
  },
});
